#include <glm/glm.hpp>

struct Particle {
    glm::vec3 position, velocity, acceleration, force;
    float density;
    float pressure;
    uint16_t hash;
};

void integratePosition(Particle* p, float deltaTime) {
    p->position += p->velocity * deltaTime;
}

int main() {
    Particle p;
    p.position = glm::vec3(0.0f, 0.0f, 0.0f);
    p.velocity = glm::vec3(1.0f, 2.0f, 3.0f);
    integratePosition(&p, 0.1f);
    return 0;
}

